-- Questões originais de estudo baseadas em Date, tradução da 8ª edição (2004).
-- Não são questões oficiais do CP-T nem exercícios transcritos do livro.
-- Execute após configurar public.questions, usando uma conta administrativa.
-- Todos os itens são rascunhos: revise no painel antes de publicar.
-- Páginas referem-se ao arquivo PDF fornecido, não à paginação impressa.
-- IDs fixos: reexecutar não duplica nem sobrescreve os registros deste lote.
-- As explicações acompanham o contexto histórico da edição, quando pertinente.
-- Capítulo 22: Apoio à decisão — 20 questões.
BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('f55dee65-2d2d-5feb-92c0-7d14413d4873', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Médio', 'Uma carga típica de apoio à decisão se destaca por:', '["Somente pequenas atualizações unitárias previsíveis.","Ausência de agregações.","Obrigação de escrever em todas as consultas.","Impossibilidade de usar histórico.","Consultas analíticas complexas sobre grandes conjuntos de dados."]'::jsonb, 4, 'O perfil analítico difere da rotina operacional de transações curtas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.2, páginas 1105–1107 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a11e036b-6f17-5ffb-ae16-7de755a018d0', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Médio', 'Um banco predominantemente de leitura voltado à análise não significa que:', '["Possa manter histórico.","Nunca precise de carga ou renovação dos dados.","Seja adequado a consultas agregadas.","Possa usar índices.","Possa reunir informação de várias fontes."]'::jsonb, 1, 'O perfil de uso não elimina operações de manutenção.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.2, páginas 1105–1107 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('af38d137-83da-5e29-9ecd-3637bccc4a1c', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Médio', 'No projeto analítico, a preocupação com desempenho deve ser conciliada com:', '["Ausência de documentação.","Remoção obrigatória de toda restrição.","Bom projeto lógico e controle da redundância.","Proibição de chaves.","Descarte da semântica dos dados."]'::jsonb, 2, 'Date alerta contra confundir requisitos físicos de desempenho com decisões lógicas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.3, páginas 1108–1119 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1b16ee7a-a27a-5ebd-8a98-1784f478fef5', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Fácil', 'A etapa de extração obtém dados:', '["Somente após apagar as fontes.","Apenas de tabelas sem chaves.","Somente de relatórios impressos.","Das fontes que alimentarão o ambiente analítico.","Exclusivamente do catálogo de senhas."]'::jsonb, 3, 'Extração integra o processo de preparação, junto de limpeza, transformação e carga.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.4, páginas 1120–1123 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9244fbf0-cc97-5ab8-83d7-3a0d5546e10c', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Médio', 'Padronizar códigos de município usados de formas diferentes em duas fontes é exemplo de:', '["Criptografia obrigatória.","Projeção sem atributos.","Bloqueio exclusivo global.","Transformação e consolidação de dados.","Commit de duas fases necessariamente."]'::jsonb, 3, 'A integração exige compatibilizar representações e significados das fontes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.4, páginas 1120–1123 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f01463d7-d4d7-53ca-bdb3-d67ec11e172f', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Fácil', 'Identificar datas inválidas e registros inconsistentes pertence principalmente à:', '["Classificação de índices.","Limpeza de dados.","Definição de senhas.","Fragmentação física.","Assinatura digital."]'::jsonb, 1, 'Qualidade dos dados precisa ser tratada antes e durante sua incorporação analítica.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.4, páginas 1120–1123 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('654d9241-f51c-5c48-b6c8-12d1b7d1a233', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Médio', 'Uma área intermediária de preparação pode servir para:', '["Organizar a integração antes da carga no destino analítico.","Garantir ausência de qualquer falha.","Eliminar a necessidade de transformação.","Substituir automaticamente o banco de origem.","Guardar somente privilégios."]'::jsonb, 0, 'O capítulo discute depósitos operacionais também como apoio à preparação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.4, páginas 1120–1123 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('be6dd5c1-61c2-5705-89d5-68a5dce8bc94', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Médio', 'Um data mart pode ser entendido como:', '["Um ambiente analítico especializado em determinado domínio ou finalidade.","Uma linguagem de consulta.","Um backup sem possibilidade de leitura.","Um índice obrigatório de todo warehouse.","Uma transação não confirmada."]'::jsonb, 0, 'O recorte especializado o distingue de um warehouse de alcance mais amplo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.5, páginas 1124–1132 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('762c09b1-96a4-5f43-bc3f-14a54fe88c4e', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Médio', 'Uma razão para separar processamento operacional e analítico é:', '["Evitar conflitos entre cargas com perfis diferentes.","A impossibilidade matemática de consultar dados operacionais.","A ausência de tipos em ambientes operacionais.","A obrigação de usar produtos diferentes.","A proibição de manter dados históricos."]'::jsonb, 0, 'Consultas analíticas extensas podem competir com transações operacionais por recursos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.5, páginas 1124–1132 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5a625490-88bf-541d-ae96-60c8ede507dd', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Médio', 'Em um esquema em estrela, a tabela de fatos contém principalmente:', '["Somente nomes de usuários.","Exclusivamente permissões.","Medidas e referências às dimensões no grão escolhido.","Somente programas de carga.","Apenas definições de tipos."]'::jsonb, 2, 'Fatos representam eventos ou observações analisáveis em determinado nível de detalhe.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.5, páginas 1124–1132 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('361634d4-224a-5543-90ea-ef2bac924b19', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Médio', 'Uma dimensão representa principalmente:', '["Apenas totais gerais sem descrição.","Contextos de análise, como tempo, produto ou local.","Um mecanismo de autenticação.","Uma transação distribuída.","Somente a quantidade física de discos."]'::jsonb, 1, 'Dimensões organizam perspectivas pelas quais as medidas podem ser analisadas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.5, páginas 1124–1132 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('cfbd5f6c-4c3e-513d-a8fd-9cbe3441a6a9', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Médio', 'Definir o grão de uma tabela de fatos significa estabelecer:', '["A ordem física obrigatória das linhas.","O tamanho do nome da tabela.","A senha do processo de carga.","A quantidade de usuários.","O que cada linha de fato representa."]'::jsonb, 4, 'Misturar níveis de detalhe sem controle pode produzir agregações incorretas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.5, páginas 1124–1132 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d9145c03-74ba-580e-903b-6566b7d74093', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'Guardar totais diários e mensais como se fossem fatos do mesmo nível pode causar:', '["Eliminação da redundância.","Garantia automática de exatidão.","Ausência de necessidade de filtros.","Dupla contagem em agregações inadequadas.","Independência de qualquer dimensão."]'::jsonb, 3, 'É necessário distinguir o grão e a semântica dos valores agregados.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.5, páginas 1124–1132 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('73cd5b30-bbe1-59b7-b091-38f103dc227f', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'OLAP está associado à análise de dados por:', '["Múltiplas dimensões e níveis de agregação.","Apenas verificação de senhas.","Exclusivamente recuperação de mídia.","Navegação física por ponteiros.","Somente edição unitária de registros."]'::jsonb, 0, 'A perspectiva multidimensional pode ser apoiada por diferentes representações e implementações.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.6, páginas 1133–1143 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('17c06e3f-3483-50ff-98da-0960813e1263', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'Passar de totais anuais para mensais corresponde a:', '["Roll-up.","Revoke.","Rollback.","Checkpoint.","Drill-down."]'::jsonb, 4, 'O detalhamento desce na hierarquia da dimensão temporal.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.6, páginas 1133–1143 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('06653966-5e5c-5074-b270-bf59802a930a', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Fácil', 'Consolidar totais municipais em totais estaduais corresponde a:', '["Drill-down.","Criação de savepoint.","Roll-up.","Undo.","Semijunção obrigatória."]'::jsonb, 2, 'A operação sobe para um nível mais agregado da dimensão.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.6, páginas 1133–1143 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5144ba57-3a92-5201-813e-95064e59f9f3', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Médio', 'O CUBE sobre duas dimensões permite calcular:', '["Apenas produtos cartesianos.","Apenas a dimensão escolhida como chave.","Somente o total mais detalhado.","Agregações para todas as combinações de subconjuntos dessas dimensões.","Somente uma soma sem agrupamento."]'::jsonb, 3, 'Inclui agrupamentos detalhados, parciais e total geral conforme a semântica da agregação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.6, páginas 1133–1143 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8fa7bc35-9492-531f-9800-ac2eb7ed2f22', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Médio', 'Duas dimensões independentes de agrupamento admitem quantos subconjuntos para um CUBE completo?', '["2.","5.","3.","8.","4."]'::jsonb, 4, 'Os subconjuntos são vazio, primeira dimensão, segunda dimensão e ambas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.6, páginas 1133–1143 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7ea5b47b-3154-50f4-a559-12a6403e1852', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Fácil', 'Mineração de dados procura principalmente:', '["Somente a definição de visões.","Somente uma linha por sua chave.","Padrões interessantes em grandes coleções de dados.","Apenas concessões de privilégio.","Exclusivamente arquivos corrompidos."]'::jsonb, 2, 'A análise exploratória pode apoiar decisões e detectar comportamentos incomuns.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.7, páginas 1144–1146 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7f2458b1-b652-533f-aed0-2bc495879ea5', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Médio', 'Detectar um aumento incomum de operações de um cartão é exemplo de:', '["Normalização até FNBC.","Busca de padrões ou anomalias para apoiar investigação.","Uma dependência funcional trivial.","Prova definitiva de fraude em qualquer caso.","Restauração de backup."]'::jsonb, 1, 'O padrão é um indício para análise, não uma conclusão automática sobre sua causa.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.7, páginas 1144–1146 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false)
ON CONFLICT (id) DO NOTHING;

COMMIT;
